fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(end < v.len(), "end must be within bounds");

    let mut max_val = v[0];
    let mut max_idx = 0usize;

    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }

    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(start < v.len(), "start must be within bounds");

    let mut min_val = v[start];
    let mut min_idx = start;

    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }

    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(p < v.len(), "p must be within bounds");

    // If p is the last index, there is no right side; condition is vacuously true.
    if p + 1 >= v.len() {
        return true;
    }

    let (left_max, _) = find_max_in_prefix(v, p);
    let (right_min, _) = find_min_in_suffix(v, p + 1);

    left_max < right_min
}